TOOL_TARGETS = _load_targets()
TOOL_BY_ID = {tool["tool_id"]: tool for tool in TOOL_TARGETS}
TOOL_BY_NAME = {tool["canonical_name"].casefold(): tool for tool in TOOL_TARGETS}


def get_tool(tool_id: str) -> dict[str, Any] | None:
    """Return a registry record by stable ID; display names are not permission keys."""
    return TOOL_BY_ID.get(str(tool_id or "").strip().upper())


def find_tool(query: str) -> tuple[dict[str, Any], ...]:
    """Find targets by ID/name, workbench, route, or description without authorizing them."""
    needle = str(query or "").strip().casefold()
    if not needle:
        return TOOL_TARGETS
    return tuple(
        tool for tool in TOOL_TARGETS
        if needle in tool["tool_id"].casefold()
        or needle in tool["canonical_name"].casefold()
        or needle in tool["workbench"].casefold()
        or needle in tool["existing_module_or_route"].casefold()
        or needle in tool["calculation_or_action"].casefold()
    )


def tier_allows_tool(tier: str, tool_id: str) -> bool:
    """Fail closed for unknown target IDs; use the stable ID for entitlement decisions."""
    tool = get_tool(tool_id)
    if tool is None:
        return False
    return tier_allows(tier, tool["target_minimum_tier"])


def require_tool_access(tier: str, tool_id: str) -> dict[str, Any]:
    """Raise a safe permission error for unknown or tier-denied target capability IDs."""
    tool = get_tool(tool_id)
    if tool is None:
        raise PermissionError("Unknown Shoir-IE tool ID; access denied.")
    if not tier_allows_tool(tier, tool_id):
        raise PermissionError(
            f"{tool_id} requires the {tool['target_minimum_tier']} package."
        )
    return tool


def tool_status_counts() -> dict[str, int]:
    counts = Counter(tool["implementation_status"] for tool in TOOL_TARGETS)
    return {status: counts.get(status, 0) for status in TOOL_STATUS_VALUES}


def validate_tool_registry() -> list[str]:
    """Return contract errors without mutating the catalog or granting access."""
    errors: list[str] = []
    expected_ids = [f"T{i:03d}" for i in range(1, 101)]
    actual_ids = [tool["tool_id"] for tool in TOOL_TARGETS]
    if actual_ids != expected_ids:
        errors.append("Tool IDs must be exactly T001 through T100 in stable order.")
    if len({tool["canonical_name"] for tool in TOOL_TARGETS}) != 100:
        errors.append("Canonical target names must be unique.")
    for tool in TOOL_TARGETS:
        if tool["target_minimum_tier"] not in TOOL_TIER_ORDER:
            errors.append(f"{tool['tool_id']} has an invalid minimum tier.")
        if tool["implementation_status"] not in TOOL_STATUS_VALUES:
            errors.append(f"{tool['tool_id']} has an invalid readiness status.")
        for key in ("workbench", "calculation_or_action", "input_contract", "output_contract", "remaining_gap"):
            if not str(tool.get(key, "")).strip():
                errors.append(f"{tool['tool_id']} is missing {key}.")
    return errors


